import json, sys
print(sys.version)
try:
    v = json.loads('1' * 5000)
    print('big int ok', type(v), v.bit_length())
except Exception as e:
    print('big int error:', type(e).__name__, str(e)[:100])
try:
    v = json.loads('1e400')
    print('1e400 ->', v)
except Exception as e:
    print('1e400 error:', e)
